import { HTMLAttributes, ReactNode } from 'react';
import { cn } from './cn';

export function Card({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn('rounded-ds border border-line bg-surface shadow-ds', className)}
      {...props}
    />
  );
}

export interface CardHeaderProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  title: ReactNode;
  /** Texto secundário cinza ao lado do título, ex.: "últimas 24 horas". */
  subtitle?: ReactNode;
  /** Ação à direita — geralmente um <Button> ou <Segmented>. */
  action?: ReactNode;
}

/** Cabeçalho padrão de card: título + subtítulo inline + ação à direita. */
export function CardHeader({ title, subtitle, action, className, ...props }: CardHeaderProps) {
  return (
    <div
      className={cn('flex items-center justify-between border-b border-line px-6 py-4', className)}
      {...props}
    >
      <h2 className="text-md font-semibold tracking-tight text-tx">
        {title}
        {subtitle && <span className="ml-2 font-normal text-tx3">{subtitle}</span>}
      </h2>
      {action}
    </div>
  );
}

export function CardBody({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('px-6 py-6', className)} {...props} />;
}

/** Rodapé de card com ações — usado em formulários (steps) e listas de exceção. */
export function CardFooter({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn('flex justify-end gap-2 border-t border-line px-6 py-4', className)}
      {...props}
    />
  );
}
